from pathlib import Path
import json
R=Path(__file__).resolve().parent
P=json.loads((R/'shared/parts.json').read_text())
source=P['source'].replace('What the client said','The supplied statement').replace('Inspect the complete supplied passage','Read source · line 14').replace('<div class="absence">','<div class="absence" data-trace-part="amount">').replace('<div class="transcript">','<div class="transcript" data-trace-part="event">')
instruction=P['instruction'].replace('Read scope & version','INS-01@1 · scope & version').replace('Preserve the statement.<br>Keep the gaps.','Keep the event. Leave gaps unresolved.')
context='''<section class="context artifact" data-node="context"><div class="eyebrow">03 / Context · FenX field meaning</div><h3>Whose information<br>does this describe?</h3><div class="field-specimen" data-trace-part="field"><div class="field-subject"><span>SUBJECT</span><b>Natural-person client</b></div><div class="field-branch"><span>Candidate event description</span><code>sourceOfWealthSignificantEvent</code></div><div class="field-branch unresolved-branch"><span>Category · lookup not supplied</span><code>individualSourceOfWealth</code></div></div><p class="context-normal">A reported field reference informs mapping. It supplies no current customer value.</p><p class="context-missing" hidden>Field meaning removed. Keep the statement, but withhold the proposed field mapping.</p><button class="inspect" data-object="MAP-01@1">Inspect field & mapping <span>↗</span></button><button class="inspect context-detail" data-object="CTX-FENX@2026-08-18">Subject distinctions & reference version <span>↗</span></button></section>'''
method=P['method'].replace('<ol>','<ol class="method-steps">').replace('Inspect inputs & failure modes','Inputs & failure modes')
output=P['output'].replace('Client states that they sold<br>their company in 2024.','Client states that they sold their company in 2024.').replace('Inspect preparation & reported schema','Inspect full output & schema').replace('<h2>','<h2 data-trace-part="event">').replace('<div class="output-field">','<div class="output-field" data-trace-part="field">').replace('<div><dt>Amount','<div data-trace-part="amount"><dt>Amount')
review=P['review'].replace('Is this faithful<br>to the source?','A colleague decides<br>what is usable.').replace('<div class="decision">','<div class="decision"><p class="review-boundary">Preparation can be accepted for this task. Assessment, approval and record changes remain separate.</p>').replace('Why reuse needs a separate review','Inspect the separate reuse review')
req=P['requirement'].replace('<h3>Make absence testable.</h3>','<h3>Specify expected behaviour.</h3>').replace('<p>','<p data-trace-part="amount">').replace('Inspect requirement & mapping','Open REQ-01@1')
test=P['test'].replace('<h3>Challenge an invented amount.</h3>','<h3>Challenge an invented amount.</h3><div class="test-diff"><span><s>amount: guessed value</s></span><span>amount: unresolved</span></div>').replace('<p>','<p data-trace-part="amount">').replace('Inspect fixture & negative cases','Open TEST-01@1')
test=test.replace('Acceptance case · TEST-01@1','Proposed test · TEST-01@1').replace('<b>Fixture:</b> line 14 has no proceeds.<br><b>Expected:</b> no fabricated amount.<br><b>Also challenge:</b> wrong subject and unsupported verification.','<b>Fixture:</b> line 14; no proceeds stated.<br><b>Also challenge:</b> wrong subject or unsupported verification.')
evid=P['evidence'].replace('No observed run supplied.','Evidence is still missing.').replace('Inspect evidence record','Open EVID-01@1')
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Useful work first · Revised workbench · CLM AI Knowledge Hub</title><link rel="stylesheet" href="../shared/useful.css"><link rel="stylesheet" href="revision.css"><script src="../shared/objects.js" defer></script><script src="../shared/useful.js" defer></script><script src="revision.js" defer></script></head><body class="architecture-revised"><header class="top"><a href="../../">CLM AI <span>Knowledge Hub</span></a><span class="section-name">Useful work first</span><nav aria-label="Design comparison"><a href="../direction-a/">A</a><a href="../direction-b/">B</a><a href="../direction-c/">C</a><a href="./" aria-current="page">Revised workbench</a></nav><span class="prototype">Synthetic teaching case · design study</span></header><main><div class="intro"><div><div class="eyebrow">Useful work first / Client information preparation</div><h1>Prepare a source-linked CLM observation.</h1></div><div class="intro-right"><p>See what the source supports, how context shapes preparation, and what remains for a colleague to decide.</p><span>One source-of-wealth example within broader CLM work.</span></div></div><div class="reading-bar"><div><b>Follow one statement through the work</b><span>Source & instruction → context & method → output → human review</span></div><div class="trace-controls" aria-label="Trace one relationship"><span>Trace</span><button data-trace="event" aria-pressed="true">Stated event</button><button data-trace="field" aria-pressed="false">Field meaning</button><button data-trace="amount" aria-pressed="false">Missing amount</button></div></div><div class="complete-work"><div class="source-column">{source}<div class="attached-instruction">{instruction}</div></div><div class="meaning-column">{context}{method}</div><div class="output-column">{output}<div class="trace-caption" role="status" data-trace-status>The event is reported by the client. The prepared description retains that attribution and line 14.</div></div><div class="review-column">{review}<div class="reuse-local"><span class="eyebrow">A second decision</span><h3>What may another task reuse?</h3><p>Selected context or methods need applicability, ownership, maintenance and permitted use. An accepted output does not grant these.</p></div></div></div><div class="evidence-bench"><div class="bench-title"><span class="eyebrow">Development & assurance</span><h2>The same instruction<br>also defines a test.</h2><p>Expected behaviour and observed evidence remain distinct.</p></div>{req}{test}{evid}</div><div class="conditions"><div><b>Supplied-material route</b><span>Useful preparation does not need a live FenX interface.</span></div><label><input type="checkbox" data-context-toggle checked> Include reported FenX field context</label><div><b>Bounded next decision</b><span>Review field applicability and missing facts before any operational use. No runtime, write permission or current interface is established here.</span></div></div></main><footer class="page-footer"><span>Source & instruction: synthetic · FenX reference: reported, 18 Aug 2026 · test: proposed, not executed</span><span>Approved SEB font binary not supplied; system fallback rendered.</span></footer><dialog aria-labelledby="detail-title"><div class="dialog-top"><span>Object inspection · retain version and scope</span><button data-close aria-label="Close inspection">Close ×</button></div><div id="detail-body"></div></dialog></body></html>'''
(R/'revised/index.html').write_text(html)
